/// **Dart 實作、Swift 呼叫。** 作業詳情與繳交，流程照 `CourseAssignmentController`
/// 與 `CourseAssignSubmitController`。繳交頁的草稿留在 Dart，Swift 每一次操作都拿回整份畫面。
///
/// Generated protocol from Pigeon that represents Flutter messages that can be called from Swift.
protocol TatAssignmentApiProtocol {
  /// 清單抓過的作業與狀態直接沿用；[refresh] 為 true 時兩個都重抓。
  func detail(courseId courseIdArg: String, assignId assignIdArg: Int64, refresh refreshArg: Bool, completion: @escaping (Result<AssignmentDetailResult, PigeonError>) -> Void)
  func submitForGrading(assignId assignIdArg: Int64, acceptStatement acceptStatementArg: Bool, completion: @escaping (Result<AssignWriteResult, PigeonError>) -> Void)
  func removeSubmission(assignId assignIdArg: Int64, completion: @escaping (Result<AssignWriteResult, PigeonError>) -> Void)
  func copyPrevious(assignId assignIdArg: Int64, completion: @escaping (Result<AssignWriteResult, PigeonError>) -> Void)
  /// 網頁版作業頁，已換成免登入網址。
  func webLink(assignId assignIdArg: Int64, completion: @escaping (Result<WebLink?, PigeonError>) -> Void)
  /// 開繳交頁：作業與狀態兩個都要是這一趟抓到的，否則回 null。
  func openSubmit(assignId assignIdArg: Int64, completion: @escaping (Result<SubmitState?, PigeonError>) -> Void)
  func setText(assignId assignIdArg: Int64, text textArg: String, completion: @escaping (Result<SubmitState, PigeonError>) -> Void)
  func setAccepted(assignId assignIdArg: Int64, accepted acceptedArg: Bool, completion: @escaping (Result<SubmitState, PigeonError>) -> Void)
  /// 挑回來的檔案，類型不合、太大與重名的擋掉，理由放在 [SubmitState.messages]。
  func addFiles(assignId assignIdArg: Int64, paths pathsArg: [String], completion: @escaping (Result<SubmitState, PigeonError>) -> Void)
  /// [index] 是 [SubmitState.files] 裡的位置。伺服器上的那一份只是標記、撤得回來；
  /// 這次剛挑的直接拿掉。
